ion to preserve `console.error` and `console.warn` in production builds, ensuring critical error messages are not silently swallowed.","tree":{"sha":"46ea2d7617482ab428ce667b25b49ea48c3d7f1c","url":"https://api.github.com/repos/bkincz/clutch/git/trees/46ea2d7617482ab428ce667b25b49ea48c3d7f1c"},"url":"https://api.github.com/repos/bkincz/clutch/git/commits/5ab08a804e5960e90455157342ec344697c5e008","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/9403180?v=4","events_url":"https://api.github.com/users/bkincz/events{/privacy}","followers_url":"https://api.github.com/users/bkincz/followers","following_url":"https://api.github.com/users/bkincz/following{/other_user}","gists_url":"https://api.github.com/users/bkincz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/bkincz","id":9403180,"login":"bkincz","node_id":"MDQ6VXNlcjk0MDMxODA=","organizations_url":"https://api.github.com/users/bkincz/orgs","received_events_url":"https://api.github.com/users/bkincz/received_events","repos_url":"https://api.github.com/users/bkincz/repos","site_admin":false,"starred_url":"https://api.github.com/users/bkincz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/bkincz/subscriptions","type":"User","url":"https://api.github.com/users/bkincz","user_view_type":"public"},"html_url":"https://github.com/bkincz/clutch/commit/5ab08a804e5960e90455157342ec344697c5e008","node_id":"C_kwDOPdpGPNoAKDVhYjA4YTgwNGU1OTYwZTkwNDU1MTU3MzQyZWMzNDQ2OTdjNWUwMDg","parents":[{"html_url":"https://github.com/bkincz/clutch/commit/6c507433a2d9d0274f410c9669ed9261f154d487","sha":"6c507433a2d9d0274f410c9669ed9261f154d487","url":"https://api.github.com/repos/bkincz/clutch/commits/6c507433a2d9d0274f410c9669ed9261f154d487"}],"sha":"5ab08a804e5960e90455157342ec344697c5e008","url":"https://api.github.com/repos/bkincz/clutch/commits/5ab08a804e5960e90455157342ec344697c